<section class="content-card"><div class="section-heading"><div><h2>Remessas de amostras</h2><p>Monte e acompanhe lotes enviados ao LCQH.</p></div><?php if(\BloodHub\Core\Permission::can('shipments.create')): ?><a class="button" href="/samples/shipments/create">+ Nova Remessa</a><?php endif; ?></div>
<div class="sample-tabs"><button class="sample-tab active" type="button" data-tab="shipments">Remessas</button><button class="sample-tab" type="button" data-tab="samples">Todas as Amostras</button></div>
<div data-panel="shipments"><div class="table-wrap"><table><thead><tr><th>Nº da remessa</th><th>Data</th><th>Unidade / origem</th><th>Destino</th><th>Amostras</th><th>Responsável</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($shipments as $item): ?><tr><td><strong><?= htmlspecialchars($item['shipment_code']) ?></strong></td><td><?= date('d/m/Y H:i',strtotime($item['created_at'])) ?></td><td><?= htmlspecialchars($item['origin_name']) ?></td><td><?= htmlspecialchars($item['destination_name']) ?></td><td><?= (int)$item['sample_count'] ?></td><td><?= htmlspecialchars($item['responsible_name']) ?></td><td><span class="status status-<?= htmlspecialchars($item['status'],ENT_QUOTES,'UTF-8') ?>"><?= htmlspecialchars(\BloodHub\Core\StatusLabel::label($item['status']),ENT_QUOTES,'UTF-8') ?></span></td><td><a class="table-action" href="/samples/shipments/view?id=<?= (int)$item['id'] ?>">Abrir</a></td></tr><?php endforeach; ?><?php if(!$shipments): ?><tr><td colspan="8" class="empty">Nenhuma remessa cadastrada.</td></tr><?php endif; ?></tbody></table></div></div>
<div data-panel="samples" hidden><div class="table-wrap"><table><thead><tr><th>Identificação</th><th>Hemocomponente</th><th>Origem</th><th>Status</th><th>Cadastro</th></tr></thead><tbody><?php foreach($samples as $item): ?><tr><td><?= htmlspecialchars($item['sample_code']) ?></td><td><?= htmlspecialchars($item['component_name']??'—') ?></td><td><?= htmlspecialchars($item['unit_name']??'—') ?></td><td><span class="status status-<?= htmlspecialchars($item['status'],ENT_QUOTES,'UTF-8') ?>"><?= htmlspecialchars(\BloodHub\Core\StatusLabel::label($item['status']),ENT_QUOTES,'UTF-8') ?></span></td><td><?= date('d/m/Y H:i',strtotime($item['registered_at'])) ?></td></tr><?php endforeach; ?><?php if(!$samples): ?><tr><td colspan="5" class="empty">Nenhuma amostra legada fora de remessa.</td></tr><?php endif; ?></tbody></table></div></div></section>
<script>document.querySelectorAll('.sample-tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.sample-tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==b.dataset.tab)}));</script>
